import {fresh,node,uid,validate,today,daysLeft,progress,pathOf,search,removeNode,descendants,safeUrl,setCompletion,weekStart,addDays,weekNumber} from './model.js';
import {guidance,officialUrl} from './guidance.js';
import {firebaseConfig} from './firebase-config.js';
import {CloudSync} from './cloud.js';
import {SYLLABUSES,profileKey,profileSeed,profileBackup} from './profiles.js';
import {NOTE_COLORS,plainRuns,richHTML,richText,readRichEditor,applyRichFormat,exportNotePDF} from './rich-notes.js';
const $=s=>document.querySelector(s), main=$('#main'), dlg=$('#editor');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const records=await fetch('./source-records.json').then(r=>{if(!r.ok)throw new Error('Cannot load curriculum');return r.json();}).catch(e=>{main.innerHTML='<p>Could not load the curriculum. Open the site through GitHub Pages or a local HTTP server; do not double-click index.html.</p>';throw e;});
const jilcce=await fetch('./jilcce-curriculum.json').then(r=>{if(!r.ok)throw new Error('JILCCE curriculum file missing. Upload every file in the update package.');return r.json();});
let activeSyllabus=null,authReady=false,currentUid=null;const requestedRoute=location.hash.startsWith('#node/')?location.hash:null;let firstChoice=true;
let key='abhyas-v1-demo',state,dirty=false,epoch=0,cloud=null,timer,editorSave,tabConflict=false;
const ui={more:null,tab:'description',edit:null,noteDraft:null,noteRichDraft:null,noteDirty:false,copyId:null};let lastHash=location.hash||'#home';
function resetUI(){Object.assign(ui,{more:null,tab:'description',edit:null,noteDraft:null,noteRichDraft:null,noteDirty:false,copyId:null});}
function ensureWeekAnchor(){if(!state.settings.weekAnchor)state.settings.weekAnchor=weekStart([today(),...state.plans.map(p=>p.date)].sort()[0]);}
function load(){try{const raw=localStorage.getItem(key);if(raw){const box=JSON.parse(raw);state=profileBackup(box.state,activeSyllabus||'nimcet');ensureWeekAnchor();dirty=box.dirty===true;return;}}catch(e){toast('Existing local data is invalid. Download a recovery copy from Account.');}
 state=profileSeed(activeSyllabus||'nimcet',records,jilcce);ensureWeekAnchor();dirty=false;
}
function persist(){try{localStorage.setItem(key,JSON.stringify({state,dirty,revision:cloud?.rev??0}));return true;}catch(e){toast('Local storage full/unavailable. Export a JSON backup now.');$('#sync').textContent='Storage error · export backup now';return false;}}
function commit(change){if(tabConflict)throw new Error('Another tab changed this tracker. Export a backup and reload first.');const next=structuredClone(state);change(next);next.updatedAt=new Date().toISOString();validate(next);state=next;dirty=true;epoch++;persist();schedule();render();}
function schedule(delay=1200){clearTimeout(timer);timer=setTimeout(()=>cloud?.push(),delay);}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',5000);}
function bar(p){return `<div class="bar"><span style="width:${p.percent}%"></span></div><small>${p.done} / ${p.total} nodes · ${p.percent}%</small>`;}
function button(action,label,attrs='',cls=''){return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;}
function field(name,label,value='',type='text',attrs=''){return `<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;}
function area(name,label,value=''){return `<label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="50000">${esc(value)}</textarea>`;}
function select(name,label,options,value=''){return `<label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`;}
function edit(title,body,save){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#form-error').textContent='';editorSave=save;dlg.showModal();setTimeout(()=>$('#dialog-body input, #dialog-body textarea, #dialog-body select')?.focus(),30);}
$('#edit-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await editorSave(data);dlg.close();render();}catch(err){$('#form-error').textContent=err.message;}};
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>dlg.close();
function syllabusName(){return SYLLABUSES[activeSyllabus]?.title||'Study Tracker';}
function loginScreen(){return `<section class="login-screen"><div class="eyebrow">YOUR PRIVATE STUDY SPACE</div><h1>Sign in to begin</h1><p>One Google account. Two separate study trackers.</p><div class="card"><h2>NIMCET 2027 + JILCCE / JSSC</h2><p>Your topics, notes, plans and progress stay private to your account.</p>${firebaseConfig?button('login','Continue with Google','','primary'):'<div class="notice">Firebase is not configured. Keep your existing firebase-config.js when uploading this update.</div>'}<p class="muted small-note">${authReady?'Sign in, then choose which syllabus you want to study.':'Checking your saved sign-in…'}</p><a href="./START-HERE-HI.html" target="_blank" rel="noopener">Setup guide (Hindi)</a></div></section>`;}
function chooserScreen(){return `<section class="syllabus-chooser"><div class="eyebrow">CHOOSE YOUR STUDY TRACKER</div><h1>What will you study?</h1><p class="muted">${esc(cloud?.user?.email||'Signed in')} · Your two study spaces remain separate.</p><div class="grid"><button class="card syllabus-choice" data-action="choose-syllabus" data-syllabus="nimcet"><span class="eyebrow">EXISTING TRACKER</span><h2>NIMCET 2027</h2><p>389 supplied lectures · Mathematics, Reasoning, Computer, English and Quantitative Aptitude.</p><strong>Open NIMCET →</strong></button><button class="card syllabus-choice" data-action="choose-syllabus" data-syllabus="jilcce"><span class="eyebrow">NEW STUDY TRACKER</span><h2>JILCCE / JSSC</h2><p>${esc(jilcce.nodes.filter(n=>n.parentId===null).map(n=>n.title.split(' (')[0]).join(' · '))}</p><strong>Open JILCCE →</strong></button></div><p class="footer-note">The JILCCE PDF is a supplied study guide. Its question counts and importance claims are not verified as official exam rules.</p>${button('logout','Logout')}</section>`;}
async function chooseSyllabus(id){if(!SYLLABUSES[id])throw new Error('Unknown syllabus.');if(!cloud?.user)throw new Error('Sign in first.');if(guardDraft())return;if(cloud.saving)throw new Error('Wait for the current cloud save.');if(activeSyllabus)persist();clearTimeout(timer);activeSyllabus=id;resetUI();cloud.selectDocument(SYLLABUSES[id].documentId);const destination=firstChoice&&requestedRoute&&state.nodes.some(n=>requestedRoute==='#node/'+n.id)?requestedRoute:'#home';firstChoice=false;location.hash=destination;lastHash=destination;render();}
function openSyllabusChooser(){if(guardDraft())return;if(cloud?.saving)throw new Error('Wait for the current cloud save.');if(activeSyllabus)persist();clearTimeout(timer);activeSyllabus=null;resetUI();cloud?.selectDocument(null);render();}
function topicLink(id){const url=new URL(location.href);if(activeSyllabus)url.searchParams.set('syllabus',activeSyllabus);url.hash='node/'+id;return url;}
function noteRuns(n){return ui.noteRichDraft??n.notesRich??plainRuns(ui.noteDraft??n.notes);}
function noteEditor(n){return `<div class="rich-note-tools" role="toolbar" aria-label="Note formatting">${button('format-note','B','data-format="bold" aria-label="Bold selected text"')}${button('format-note','I','data-format="italic" aria-label="Italic selected text"')}${button('format-note','U','data-format="underline" aria-label="Underline selected text"')}${NOTE_COLORS.slice(1).map(c=>button('format-note',`<span style="color:${c}">A</span>`,`data-format="color" data-color="${c}" aria-label="Text colour ${c}"`)).join('')}${button('format-note','Clear style','data-format="clear"')}</div><label id="rich-note-label">Your notes · select text, then choose a colour or style</label><div id="inline-notes" class="rich-editor" role="textbox" contenteditable="true" aria-labelledby="rich-note-label" aria-multiline="true" data-note-id="${n.id}">${richHTML(noteRuns(n))}</div><div class="actions">${button('save-notes','Save notes',`data-id="${n.id}"`,'primary')}${button('cancel-notes','Cancel')}${button('export-note-pdf','Export PDF',`data-id="${n.id}"`)}</div><p class="muted small-note">Export PDF opens the print dialog. Choose Save as PDF. Hindi text and colours use your browser fonts.</p>`;}
function hasDraft(){return !!ui.edit||ui.noteDirty;}
function guardDraft(){if(!hasDraft())return false;toast('Save or cancel your current changes first.');return true;}
function focusInline(selector){setTimeout(()=>$(selector)?.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'}),20);}
function topicPanel(n){const g=guidance(n,state.nodes),editing=ui.edit?.kind==='details'&&ui.edit.id===n.id,draft=editing?ui.edit.draft:null;
 return `<section class="topic-panel" id="panel-${n.id}" aria-label="Details for ${esc(n.title)}"><div class="panel-topic">${esc(n.title)}</div><div class="topic-tabs" role="tablist" aria-label="Topic details"><button type="button" id="tab-description" role="tab" aria-controls="topic-tab-body" aria-selected="${ui.tab==='description'}" data-action="topic-tab" data-tab="description">Description</button><button type="button" id="tab-notes" role="tab" aria-controls="topic-tab-body" aria-selected="${ui.tab==='notes'}" data-action="topic-tab" data-tab="notes">Notes & Links</button></div><div id="topic-tab-body" role="tabpanel" aria-labelledby="tab-${ui.tab}">${ui.tab==='description'?`
 <h3>Topic title</h3><p class="inline-text title-edit" id="inline-title" ${editing?'contenteditable="plaintext-only" role="textbox" aria-label="Edit topic title"':''}>${esc(editing?draft.title:n.title)}</p><h3>What you will study</h3><p class="inline-text" id="inline-description" ${editing?'contenteditable="plaintext-only" role="textbox" aria-label="Edit description" aria-multiline="true"':''}>${esc(editing?draft.description:g.description)}</p><h3>Exam relevance</h3><p class="inline-text" id="inline-relevance" ${editing?'contenteditable="plaintext-only" role="textbox" aria-label="Edit exam relevance" aria-multiline="true"':''}>${esc(editing?draft.relevance:g.relevance)}</p><p class="muted small-note">${editing?'Editing here · Ctrl/⌘ + Enter saves · Esc cancels':'Added study guidance · not PDF text. No exact question frequency is claimed.'}</p>
 ${n.source?`<details class="source-details"><summary>Original lecture reference</summary><div class="metadata"><div><span>Date / day</span>${esc(n.source.dateOriginal)} · ${esc(n.source.day)}</div><div><span>Class / time</span>${esc(n.source.classSlot)} · ${esc(n.source.time)}</div><div><span>Original unit</span>${esc(n.source.unit)}</div></div><p class="source-title">${esc(n.source.title)}</p><p class="muted small-note">${esc(n.source.file)} · page ${n.source.page}</p>${n.source.footnote?`<p>${esc(n.source.footnote)}</p>`:''}${n.source.extractionNote?`<p class="muted small-note">${esc(n.source.extractionNote)}</p>`:''}</details>`:''}${n.syllabusSource?`<details class="source-details"><summary>Provided PDF reference · page ${n.syllabusSource.page}</summary><p class="muted small-note">${esc(n.syllabusSource.file)} · supplied guide, not an official notification</p><p class="notes">${esc(n.syllabusSource.excerpt)}</p><p class="muted small-note">${esc(n.syllabusSource.extractionNote||'')}</p></details>`:''}${activeSyllabus==='nimcet'?`<a class="small-note" href="${officialUrl}" target="_blank" rel="noopener noreferrer">Official syllabus ↗</a>`:'<p class="muted small-note">Use the provided guide with the official JSSC notification. No fixed question frequency is verified here.</p>'}`:`
 ${noteEditor(n)}
 ${['youtube','resource'].map(type=>`<div class="section-head resource-heading"><h3>${type==='youtube'?'YouTube videos':'Drive / PDF / photo links'}</h3>${button('add-link','+ Link',`data-id="${n.id}" data-type="${type}"`)}</div>${n.links.map((l,i)=>l.type===type?`<div class="resource"><a href="${esc(safeUrl(l.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(l.label||l.url)} ↗</a>${button('delete-link','×',`data-id="${n.id}" data-index="${i}" aria-label="Remove ${esc(l.label)}"`)}</div>`:'').join('')}${n.links.some(l=>l.type===type)?'':'<p class="muted small-note">No links yet.</p>'}`).join('')}<p class="muted small-note">Store files in Drive and add links here. Drive sharing permissions control access.</p>`}</div>
 <div class="topic-action-line">${editing?`<div class="save-cancel">${button('save-details','Save',`data-id="${n.id}"`,'primary')}${button('cancel-inline','Cancel')}</div>`:button('edit-node','Edit Details',`data-id="${n.id}"`)}${button('copy-link','Copy Link',`data-id="${n.id}"`)}</div>
 ${ui.edit?.kind==='link'&&ui.edit.id===n.id?inlineForm():''}${ui.copyId===n.id?`<label for="copy-topic-link">Copy this direct link</label><input id="copy-topic-link" readonly value="${esc(topicLink(n.id).href)}">`:''}
 <div class="topic-danger">${button('delete-node','Delete topic',`data-id="${n.id}"`,'danger')}</div></section>`;
}
function nodeRow(n){const p=progress(state.nodes,n.id),children=state.nodes.filter(x=>x.parentId===n.id);return `<div class="topic-row-wrap"><div class="node-row ${n.done?'done':''}"><input type="checkbox" aria-label="Complete ${esc(n.title)}" data-check="${n.id}" ${n.done?'checked':''}><a href="#node/${n.id}"><strong>${esc(n.title)}</strong><small>${children.length?`${children.length} subtopics · `:''}${p.done}/${p.total} complete</small></a>${button('more',ui.more===n.id?'Less ↑':'More ↓',`data-id="${n.id}" aria-expanded="${ui.more===n.id}" aria-label="Details for ${esc(n.title)}"`,'more-row')}</div>${ui.more===n.id?topicPanel(n):''}</div>`;}
function list(nodes,empty='No items here yet.'){return nodes.length?`<div class="list">${nodes.map(nodeRow).join('')}</div>`:`<p class="empty">${empty}</p>`;}
function section(title,body,extra=''){return `<section><div class="section-head"><h2>${title}</h2>${extra}</div>${body}</section>`;}
function goalsCard(){const mainGoal=typeof state.settings.goalMain==='string'?state.settings.goalMain:'NIT Jamshedpur',backupGoal=typeof state.settings.goalBackup==='string'?state.settings.goalBackup:'BIT Mesra';return `<section class="notice" aria-label="Your goals"><div class="row"><strong>Your goals</strong>${button('edit-goals','✎ Edit','aria-label="Edit your goals"')}</div>${ui.edit?.kind==='goals'?inlineForm():`<p>${esc(mainGoal)} · main goal${backupGoal?`<br>${esc(backupGoal)} · backup aspiration`:''}</p>`}<small>Check admission rules and eligibility with the relevant institution. No admission or cutoff outcome is guaranteed.</small></section>`;}
function home(){const p=progress(state.nodes);const d=today(),plans=state.plans.filter(x=>x.date===d),minutes=state.sessions.filter(x=>x.date===d).reduce((a,b)=>a+b.minutes,0);const left=daysLeft(state.settings.milestone);const next=state.nodes.filter(n=>n.kind==='lecture'&&n.source&&!n.done).sort((a,b)=>a.source.date.localeCompare(b.source.date)).slice(0,3);
 const nextItems=activeSyllabus==='jilcce'?state.nodes.filter(n=>!n.done&&n.kind==='custom').slice(0,3):next;
 return `<div class="eyebrow" id="live-date">${esc(new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()))} · IST</div><div class="hero"><div><div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h1>A little every day.<br>A step closer every day.</h1><p>${activeSyllabus==='jilcce'?'Prepare for JILCCE / JSSC with the supplied Hindi-English study guide. Make room for concepts, practice and revision.':'Prepare for NIT Jamshedpur, one small step at a time. Make room for concepts, practice and revision today.'}</p><a class="button lime" href="#planner">Plan today&#39;s study ↗</a></div><div class="count"><strong>${Math.max(0,left)}</strong><span>days to go</span><small>Your provisional milestone<br>${esc(state.settings.milestone)} · not an official exam date</small></div></div>
 <div class="stats"><div class="stat"><small>OVERALL PROGRESS</small><strong>${p.percent}%</strong><small>${p.done}/${p.total} nodes complete</small></div><div class="stat"><small>TODAY'S STUDY</small><strong>${minutes}<small> min</small></strong><small>Target ${state.settings.dailyMinutes} min</small></div><div class="stat"><small>TODAY'S PLAN</small><strong>${plans.filter(x=>x.done).length}/${plans.length}</strong><small>tasks complete</small></div></div>
 <div class="grid home-grid"><div>${section('Your next small step',list(nextItems),' <a href="#subjects">All subjects ↗</a>')}<p class="footer-note">${activeSyllabus==='jilcce'?'These are unfinished study topics from your provided guide.':'These are your oldest unfinished PDF lectures.'} Add them to your planner at a pace that works for you.</p></div><div>${section('Your day ahead',plans.length?planList(plans):'<div class="card"><h3>A fresh start for today.</h3><p class="muted">Suggested 150-minute split: Maths 75, Reasoning/Quant 35, Computer/English 20, revision 20. Adapt this study suggestion to your day.</p><a class="button" href="#planner">Create a plan</a></div>')}
 ${goalsCard()}</div></div>
 ${section('Your study library',subjectCards())}<p class="footer-note">${activeSyllabus==='jilcce'?`${jilcce.nodes.length} study nodes · supplied 14-page PDF guide`:'389 PDF lectures · 5 subjects'} · notes are saved in your browser. ${cloud?.user?'See cloud status above.':'Sign in with Google in Account to sync across devices.'}</p>`;
}
function subjectCards(){return `<div class="grid subjects-grid">${state.nodes.filter(n=>n.parentId===null).map((n,i)=>`<a class="card subject" href="#node/${n.id}"><span class="num">${String(i+1).padStart(2,'0')} / STUDY LIBRARY</span><span class="arrow">↗</span><h2>${esc(n.title)}</h2>${bar(progress(state.nodes,n.id))}</a>`).join('')}</div>`;}
function subjects(){return `<div class="eyebrow">STUDY LIBRARY</div><div class="section-head"><h1>Your subjects</h1>${button('add-root','+ Subject')}</div>${ui.edit?.kind==='node-add'&&ui.edit.parentId===null?inlineForm():''}${list(state.nodes.filter(n=>n.parentId===null),'Add your first subject.')}<p class="footer-note">Open a subject to see its immediate subtopics. More opens details beside the topic. Complete children before marking their parent complete.</p>`;}
function detail(id){const n=state.nodes.find(n=>n.id===id);if(!n)return '<h1>Topic not found</h1><p>This topic may have been deleted or may belong to another backup.</p><a class="button" href="#subjects">Open subjects</a>';const children=state.nodes.filter(x=>x.parentId===id),p=progress(state.nodes,id),path=pathOf(state.nodes,id);
 return `<div class="topic-path"><a class="button back-path" href="${n.parentId?'#node/'+n.parentId:'#subjects'}">← Back</a><nav aria-label="Topic path"><a href="#subjects">Subjects</a>${path.map((x,i)=>`<span aria-hidden="true">/</span>${i===path.length-1?`<strong aria-current="page">${esc(x.title)}</strong>`:`<a href="#node/${x.id}">${esc(x.title)}</a>`}`).join('')}</nav></div>
 <section class="current-topic"><h1 class="detail-title">${esc(n.title)}</h1><div class="row"><label class="complete-label"><input type="checkbox" data-check="${id}" ${n.done?'checked':''}> Mark complete</label>${button('more',ui.more===id?'Less ↑':'More ↓',`data-id="${id}" aria-expanded="${ui.more===id}"`)}</div>${bar(p)}</section>${ui.more===id?topicPanel(n):''}
 ${section(`Subtopics (${children.length})`,`${ui.edit?.kind==='node-add'&&ui.edit.parentId===id?inlineForm():''}${list(children,'No subtopics yet. Add your first one above.')}`,button('add-node','+ Add Subtopic',`data-id="${id}"`,'primary'))}`;
}
function linkedTopicMatches(query){const q=query.trim().toLocaleLowerCase();return state.nodes.map(n=>({id:n.id,label:pathOf(state.nodes,n.id).map(x=>x.title).join(' / ')})).filter(n=>!q||n.label.toLocaleLowerCase().includes(q));}
function linkedTopicChoices(query,selected){const matches=linkedTopicMatches(query);return `<div role="listbox" aria-label="Matching topics">${button('pick-linked-topic','No linked topic','data-node-id="" role="option" aria-selected="'+(!selected)+'"','search-hit')}${matches.map(n=>button('pick-linked-topic',esc(n.label),`data-node-id="${n.id}" role="option" aria-selected="${n.id===selected}"`,'search-hit')).join('')}${matches.length?'':'<p class="muted small-note">No matching topics. Try another search.</p>'}</div>`;}
function linkedTopicPicker(editor){const q=editor.topicQuery||'',selected=editor.draft.nodeId||'',chosen=state.nodes.find(n=>n.id===selected),label=chosen?pathOf(state.nodes,selected).map(x=>x.title).join(' / '):'Choose a topic…';return `<label for="linked-topic-trigger">Linked topic (optional)</label><input type="hidden" id="f-nodeId" name="nodeId" value="${esc(selected)}"><button type="button" id="linked-topic-trigger" data-action="toggle-topic-picker" aria-expanded="${!!editor.pickerOpen}" aria-controls="linked-topic-panel" style="width:100%;justify-content:space-between;text-align:left;overflow-wrap:anywhere"><span>${esc(label)}</span><span aria-hidden="true">⌄</span></button>${editor.pickerOpen?`<div id="linked-topic-panel" style="margin-top:8px;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--surface)"><label for="linked-topic-search">Search inside topics</label><input id="linked-topic-search" type="search" placeholder="Type a topic or subject name…" value="${esc(q)}" autocomplete="off" aria-controls="linked-topic-choices"><p id="linked-topic-count" role="status" class="muted small-note">${linkedTopicMatches(q).length} matching topics</p><div id="linked-topic-choices" style="max-height:240px;overflow-y:auto;display:grid;gap:5px">${linkedTopicChoices(q,selected)}</div></div>`:''}`;}
function capturePlanFields(){if(ui.edit?.kind!=='plan')return;for(const k of ['title','date','minutes']){const el=$('#f-'+k);if(el)ui.edit.draft[k]=el.value;}}
function updateLinkedTopicSearch(value){if(ui.edit?.kind!=='plan')return;ui.edit.topicQuery=value;const selected=ui.edit.draft.nodeId||'';$('#linked-topic-choices').innerHTML=linkedTopicChoices(value,selected);$('#linked-topic-count').textContent=linkedTopicMatches(value).length+' matching topics';}
function inlineForm(){const e=ui.edit;if(!e)return '';let body='';if(e.kind==='goals')body=field('goalMain','Main goal',e.draft.goalMain,'text','required maxlength="200"')+field('goalBackup','Backup goal (optional)',e.draft.goalBackup,'text','maxlength="200"');if(e.kind==='node-add')body=field('title',e.parentId?'Subtopic name':'Subject name',e.draft.title,'text','required maxlength="1000"');
 if(e.kind==='link')body=field('label','Link name',e.draft.label,'text','required maxlength="300"')+field('url','HTTP / HTTPS link',e.draft.url,'url','required maxlength="3000"');
 if(e.kind==='plan')body=field('title','Task title',e.draft.title,'text','required maxlength="1000"')+`<div class="two-fields"><div>${field('date','Date',e.draft.date,'date','required')}</div><div>${field('minutes','Planned minutes',e.draft.minutes,'number','required min="1" max="1440"')}</div></div>`+linkedTopicPicker(e);
 return `<form id="inline-form" class="inline-form" data-kind="${e.kind}"><h3>${e.kind==='goals'?'Edit your goals':e.kind==='plan'?'Plan a small task':e.kind==='link'?'Add a resource link':e.parentId?'Add subtopic':'Add subject'}</h3>${body}<p id="inline-error" role="alert"></p><div class="actions"><button type="submit" class="primary">${e.kind==='goals'?'Save goals':e.kind==='plan'?'Save task':'Add'}</button>${button('cancel-inline','Cancel')}</div></form>`;
}
let plannerDate=today(),plannerWeek=weekStart(today());
function dateLabel(d,opts={day:'numeric',month:'short'}){return new Intl.DateTimeFormat('en-GB',{...opts,timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'));}
function weekTitle(d){const number=weekNumber(state.settings.weekAnchor||weekStart(today()),d);return number>0?'Week '+number:'Earlier week';}
function planList(plans){return `<div class="list">${plans.map(p=>`<div class="plan-row ${p.done?'done':''}"><label><input type="checkbox" data-plan-check="${p.id}" aria-label="Complete task ${esc(p.title)}" ${p.done?'checked':''}><span><strong>${esc(p.title)}</strong><small>${p.minutes} min · ${esc(p.date)} ${p.nodeId?`· <a href="#node/${p.nodeId}">Topic ↗</a>`:''}</small></span></label><div class="plan-actions">${button('edit-plan','Edit',`data-id="${p.id}"`)}${button('delete-plan','×',`data-id="${p.id}" aria-label="Delete ${esc(p.title)}"`)}</div></div>`).join('')}</div>`;}
function planner(){const end=addDays(plannerWeek,6),items=state.plans.filter(p=>p.date>=plannerWeek&&p.date<=end),backlog=state.plans.filter(p=>p.date<today()&&!p.done).sort((a,b)=>a.date.localeCompare(b.date)),total=items.reduce((a,b)=>a+b.minutes,0),dates=Array.from({length:7},(_,i)=>addDays(plannerWeek,i));const tabs=[-1,0,1].map(i=>addDays(plannerWeek,i*7));if(weekNumber(state.settings.weekAnchor,plannerWeek)===1){tabs[0]=plannerWeek;tabs[1]=addDays(plannerWeek,7);tabs[2]=addDays(plannerWeek,14);}
 return `<div class="eyebrow">WEEKLY PLANNER</div><h1>One week at a time.</h1><div class="week-controls">${button('week','‹',`data-date="${addDays(plannerWeek,-7)}" aria-label="Previous week"`)}${tabs.map(d=>button('week',weekTitle(d),`data-date="${d}" aria-pressed="${d===plannerWeek}"`,d===plannerWeek?'primary':'')).join('')}${button('week','›',`data-date="${addDays(plannerWeek,7)}" aria-label="Next week"`)}</div><div class="week-summary"><strong>${dateLabel(plannerWeek)} – ${dateLabel(end,{day:'numeric',month:'short',year:'numeric'})}</strong><span>${items.filter(p=>p.done).length}/${items.length} done · ${total} min planned</span></div>
 <div class="planner-tools"><div><label for="planner-date">Jump to date</label><input id="planner-date" type="date" value="${plannerDate}"></div><div class="actions">${button('suggest-plan','150-min plan for selected day')}${button('log-session','+ Actual study minutes')}</div></div><p class="muted small-note">Daily target: ${state.settings.dailyMinutes} min. Planned tasks and actual study minutes are tracked separately.</p>
 <div class="week-grid">${dates.map(date=>{const tasks=items.filter(p=>p.date===date),mins=tasks.reduce((a,b)=>a+b.minutes,0);return `<section class="week-day ${date===today()?'today-day':''}"><div class="week-day-heading"><div><h2>${dateLabel(date,{weekday:'long'})}${date===today()?' · Today':''}</h2><small>${dateLabel(date)} · ${mins} min ${mins>state.settings.dailyMinutes?'· over target':''}</small></div>${button('add-plan','+ Task',`data-date="${date}"`)}</div>${tasks.length?planList(tasks):'<p class="empty-day">No tasks planned</p>'}${ui.edit?.kind==='plan'&&ui.edit.formDate===date?inlineForm():''}</section>`;}).join('')}</div>
 <details class="backlog"><summary>Backlog (${backlog.length})</summary>${backlog.length?planList(backlog):'<p class="muted">No overdue tasks.</p>'}</details><details class="backlog"><summary>PDF timetable · ${esc(plannerDate)}</summary>${list(state.nodes.filter(n=>n.source?.date===plannerDate),'No PDF lectures listed for this date.')}</details>`;
}
function tests(){const ts=[...state.tests].sort((a,b)=>a.date.localeCompare(b.date)),last=ts.slice(-8);const minutes=state.sessions.reduce((a,b)=>a+b.minutes,0);const days=new Set(state.sessions.map(x=>x.date)).size;
 return `<div class="eyebrow">MAKE YOUR PROGRESS VISIBLE</div><h1>See your effort add up.</h1><div class="actions">${button('add-test','+ Test marks','','primary')}${button('log-session','+ Study minutes')}</div><div class="stats"><div class="stat"><small>TESTS LOGGED</small><strong>${ts.length}</strong></div><div class="stat"><small>STUDY HOURS</small><strong>${(minutes/60).toFixed(1)}</strong></div><div class="stat"><small>ACTIVE STUDY DAYS</small><strong>${days}</strong></div></div>
 ${section('Test score trend',`<div class="card">${last.length?`<div class="chart" role="img" aria-label="Last ${last.length} test scores, percentages. Values also listed below.">${last.map((t,i)=>`<div style="height:${Math.max(2,100*t.score/t.max)}%"><b>${Math.round(100*t.score/t.max)}%</b><span>${i+1}</span></div>`).join('')}</div><small>Each bar shows a test percentage. Tests with different difficulty levels are not directly comparable.</small>`:'<p class="muted">Add your first test to see a score trend here.</p>'}</div>`)}
 <div class="list">${[...ts].reverse().map(t=>`<article class="card"><div class="row"><h2>${esc(t.title)}</h2><strong>${t.score}/${t.max}</strong></div><small>${esc(t.date)} · ${esc(t.subject)} · ${(100*t.score/t.max).toFixed(1)}%</small><p class="notes">${esc(t.notes)}</p><div class="actions">${button('edit-test','Edit',`data-id="${t.id}"`)}${button('delete-test','Delete',`data-id="${t.id}"`)}</div></article>`).join('')}</div>
 
 ${section('Study log',state.sessions.length?`<div class="list">${[...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<div class="node-row"><div style="flex:1"><strong>${esc(s.title)}</strong><small>${s.date} · ${s.minutes} minutes</small></div>${button('delete-session','×',`data-id="${s.id}" aria-label="Delete study log"`)}</div>`).join('')}</div>`:'<p class="empty">Your study minutes will appear here after you log a session.</p>')}`;
}
function settings(){return `<div class="eyebrow">YOUR SPACE / YOUR DATA</div><h1>My Account</h1><p class="muted small-note">Version r7 · Two syllabuses + rich notes · ${esc(syllabusName())}</p><div class="grid"><section class="card"><h2>Study preferences</h2><p>Provisional milestone: <strong>${esc(state.settings.milestone)}</strong><br>Daily target: <strong>${state.settings.dailyMinutes} minutes</strong></p>${button('preferences','Change target / date')}<div class="notice">${activeSyllabus==='jilcce'?'This is your provisional study milestone, not an official JILCCE exam date.':'31 May 2027 is only a planning milestone. The official 2027 exam date has not been verified here.'}</div></section>
 <section class="card"><h2>Private cross-device sync</h2><p id="cloud-detail">${esc($('#sync').textContent)}</p><p>Local mode works without sign-in. Secure private sync needs Google sign-in to identify your data. Use the same Google account on both devices.</p><p class="muted">${cloud?.user?esc(cloud.user.email||'Google account signed in'):'Your browser-local study space is open.'}</p><div class="actions">${cloud?.user?button('logout','Logout'):button('login','Google sign-in','','primary')}${button('sync-now','Retry sync')}</div>${!firebaseConfig?'<p class="notice">Firebase is not configured. This is local mode; your data is not synced.</p>':''}<a href="./START-HERE-HI.html" target="_blank" rel="noopener">Firebase + GitHub Pages setup guide (Hindi) ↗</a>
 ${cloud?.remote?`<div class="notice warning"><h3>Both versions have changes</h3><p>Export JSON first. Choosing the cloud version replaces this browser&#39;s changes; choosing the local version replaces the whole cloud tracker. There is no automatic merge.</p>${button('export','Export local backup first')}${button('resolve-cloud','Use cloud version')}${button('resolve-local','Keep local version in cloud')}</div>`:''}
 ${cloud?.user?`<p class="muted">Demo data and each Google account have separate local storage. To move demo work to the cloud, export it, sign in, then import the backup.</p>`:''}</section>
 <section class="card"><h2>Backup / restore</h2><p>JSON backups include topics, notes, links, plans, test marks, study minutes and preferences. Make a backup every week.</p><div class="actions">${button('export','Export JSON','','primary')}${button('import','Import JSON')}</div><input id="import-file" class="screen-reader" type="file" accept="application/json,.json"><p class="muted">Import replaces the entire current tracker. Export first. Invalid backups are rejected.</p>${button('recover','Download raw local recovery')}<p class="muted">Local mode is specific to this browser and site address. Clearing browser data deletes the local copy.</p></section>
 <section class="card"><h2>Sources and study guidance</h2>${activeSyllabus==='jilcce'?`<div class="notice">JILCCE: ${jilcce.nodes.length} nodes from your supplied study guide. Hindi headings normalised; raw excerpts retain PDF extraction artefacts. Safety topics, literature MCQ examples and preparation advice are labelled supplied guidance. Named books in examples are not a prescribed reading list.</div>`:''}<p>NIMCET: 389 lectures from five supplied planners. Subject → original unit → original lecture; titles, dates and class slots are retained. Teacher names are omitted. Formatting whitespace is normalized.</p><p>Descriptions, question styles and priorities are editorial suggestions, not verified PYQ frequencies or an official 2027 syllabus. Quantitative Aptitude is a separate study subject here, not a separate official exam section.</p><p>Check logic/truth tables, statistics moments/frequency distributions, and English technical writing/word formation against the official 2026 checklist. Prioritize the official core before planner extensions.</p><a href="${officialUrl}" target="_blank" rel="noopener noreferrer">Official revised syllabus (2026 onwards) ↗</a><br><a href="./source-audit.json" target="_blank" rel="noopener">PDF extraction audit ↗</a></section></div><p class="footer-note">PWA: after a successful HTTPS visit, local study features can work offline. Cloud sign-in/sync and external resources need internet. Android: browser menu → Install/Add to Home screen. iPhone: Safari Share → Add to Home Screen.</p>`;}
function render(){const open=!!(cloud?.user&&activeSyllabus);$('#app-nav').hidden=!open;$('#syllabus-bar').hidden=!open;$('#global-search').disabled=!open;if($('#syllabus-label'))$('#syllabus-label').textContent=syllabusName();document.documentElement.lang=activeSyllabus==='jilcce'?'hi':'en';document.title='Abhyas · '+(activeSyllabus?syllabusName():'Study Tracker');if(!open){$('#global-results').hidden=true;main.innerHTML=cloud?.user?chooserScreen():loginScreen();return;}const route=location.hash.slice(1)||'home';document.body.classList.toggle('dark',state.settings.theme==='dark');main.innerHTML=route==='home'?home():route==='subjects'?subjects():route==='planner'?planner():route==='tests'?tests():(route==='account'||route==='settings')?settings():route.startsWith('node/')?detail(route.slice(5)):'<h1>Page not found</h1><a href="#home">Home</a>';document.querySelectorAll('.bottom a').forEach(a=>{const active=a.dataset.route===(route.startsWith('node/')?'subjects':route==='settings'?'account':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if($('#inline-form'))$('#inline-form').onsubmit=submitInline;if($('#planner-date'))$('#planner-date').onchange=e=>{if(guardDraft()){e.target.value=plannerDate;return;}if(e.target.value){plannerDate=e.target.value;plannerWeek=weekStart(plannerDate);render();}};}
function runSearch(value){if(!cloud?.user||!activeSyllabus){$('#global-results').hidden=true;return;}const q=value.trim(),results=search(state.nodes,q),box=$('#global-results');box.hidden=!q;box.innerHTML=q?`<div class="search-result-head"><strong>${results.length} matching topics</strong>${button('close-search','×','aria-label="Close search results"')}</div><div class="list">${results.map(n=>`<a class="search-hit" href="#node/${n.id}"><strong>${esc(n.title)}</strong><small>${esc(pathOf(state.nodes,n.id).map(x=>x.title).join(' / '))} · ${n.done?'Complete':'Not complete'}</small></a>`).join('')||'<p class="muted">No matches. Try another search term.</p>'}</div>`:'';}
$('#global-search').oninput=e=>runSearch(e.target.value);
$('#global-results').onclick=e=>{if(e.target.closest('[data-action="close-search"]')){runSearch('');$('#global-search').value='';}};
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportBackup(){download('abhyas-'+(activeSyllabus||'nimcet')+'-backup-'+today()+'.json',JSON.stringify(state));}
function beginDetails(id){if(guardDraft())return;const n=state.nodes.find(n=>n.id===id),g=guidance(n,state.nodes);ui.more=id;ui.tab='description';ui.edit={kind:'details',id,draft:{title:n.title,description:g.description,relevance:g.relevance}};render();setTimeout(()=>$('#inline-description')?.focus(),20);}
function editNode(id,parent=null){if(id){beginDetails(id);return;}if(guardDraft())return;ui.edit={kind:'node-add',parentId:parent,draft:{title:''}};render();focusInline('#inline-form');setTimeout(()=>$('#f-title')?.focus(),20);}
function editPlan(id,date=plannerDate){if(guardDraft())return;const p=state.plans.find(x=>x.id===id)||{id:uid(),title:'',date,minutes:30,nodeId:null,done:false};plannerDate=p.date;plannerWeek=weekStart(p.date);ui.edit={kind:'plan',id:p.id,formDate:p.date,draft:structuredClone(p)};render();focusInline('#inline-form');}
function saveInlineDetails(){const e=ui.edit;if(e?.kind!=='details')return;const draft={title:$('#inline-title').textContent.trim(),description:$('#inline-description').textContent,relevance:$('#inline-relevance').textContent};if(!draft.title)throw new Error('A title is required.');ui.edit=null;try{commit(s=>Object.assign(s.nodes.find(n=>n.id===e.id),draft));toast('Details saved');}catch(err){ui.edit={...e,draft};render();throw err;}}
function submitInline(e){e.preventDefault();const editor=ui.edit;if(!editor)return;const values=Object.fromEntries(new FormData(e.target));const previous=structuredClone(editor);try{
 if(editor.kind==='goals'){const goalMain=(values.goalMain||'').trim(),goalBackup=(values.goalBackup||'').trim();if(!goalMain||goalMain.length>200||goalBackup.length>200)throw new Error('Enter a main goal and keep each goal within 200 characters.');ui.edit=null;commit(s=>Object.assign(s.settings,{goalMain,goalBackup}));toast('Goals saved');}

 if(editor.kind==='node-add'){const title=values.title.trim();if(!title)throw new Error('A title is required.');ui.edit=null;commit(s=>{s.nodes.push(node(uid(),editor.parentId,title));if(editor.parentId)setCompletion(s.nodes,editor.parentId,false);});}
 if(editor.kind==='link'){if(!values.label.trim()||!safeUrl(values.url))throw new Error('Enter a name and a valid HTTP/HTTPS link.');if(editor.type==='youtube'&&!/(^|\.)(youtube\.com|youtu\.be)$/.test(new URL(values.url).hostname))throw new Error('Use a youtube.com or youtu.be URL.');ui.edit=null;commit(s=>s.nodes.find(n=>n.id===editor.id).links.push({label:values.label.trim(),url:safeUrl(values.url),type:editor.type}));}
 if(editor.kind==='plan'){const next={...editor.draft,title:values.title.trim(),date:values.date,minutes:Number(values.minutes),nodeId:values.nodeId||null};ui.edit=null;commit(s=>{const i=s.plans.findIndex(p=>p.id===next.id);if(i<0)s.plans.push(next);else s.plans[i]=next;});plannerDate=next.date;plannerWeek=weekStart(next.date);render();}
 }catch(err){ui.edit=previous;ui.edit.draft={...previous.draft,...values};render();if($('#inline-error'))$('#inline-error').textContent=err.message;else toast(err.message);}}
function editTest(id){const t=state.tests.find(x=>x.id===id)||{id:uid(),title:'',date:today(),subject:'Mixed mock',score:0,max:100,notes:''};edit('Test marks',field('title','Test name',t.title,'text','required maxlength="1000"')+field('date','Date',t.date,'date','required')+select('subject','Subject',[['Mixed mock','Mixed mock'],...state.nodes.filter(n=>!n.parentId).map(n=>[n.title,n.title])],t.subject)+`<div class="two-fields"><div>${field('score','Net marks (negative allowed)',t.score,'number','step="any" required')}</div><div>${field('max','Maximum marks',t.max,'number','min="0.01" step="any" required')}</div></div>`+area('notes','Mistakes / next revision',t.notes),v=>commit(s=>{const next={...t,...v,score:Number(v.score),max:Number(v.max)};const i=s.tests.findIndex(x=>x.id===t.id);if(i<0)s.tests.push(next);else s.tests[i]=next;}));}
main.onpointerdown=e=>{if(e.target.closest('[data-action="format-note"]'))e.preventDefault();};
main.onmousedown=e=>{if(e.target.closest('[data-action="format-note"]'))e.preventDefault();};
main.onpaste=e=>{if(e.target.closest('#inline-notes')){e.preventDefault();const sel=window.getSelection();if(!sel?.rangeCount)return;const range=sel.getRangeAt(0);range.deleteContents();const text=document.createTextNode(e.clipboardData.getData('text/plain'));range.insertNode(text);range.setStartAfter(text);range.collapse(true);sel.removeAllRanges();sel.addRange(range);ui.noteRichDraft=readRichEditor($('#inline-notes'));ui.noteDraft=richText(ui.noteRichDraft);ui.noteDirty=true;}};
main.oninput=e=>{if(e.target.id==='linked-topic-search'){updateLinkedTopicSearch(e.target.value);return;}if(e.target.id==='inline-notes'){ui.noteRichDraft=readRichEditor($('#inline-notes'));ui.noteDraft=richText(ui.noteRichDraft);ui.noteDirty=true;}else if(ui.edit?.kind==='details'){const k={'inline-title':'title','inline-description':'description','inline-relevance':'relevance'}[e.target.id];if(k)ui.edit.draft[k]=e.target.textContent;}else if(ui.edit&&e.target.name)ui.edit.draft[e.target.name]=e.target.value;};
main.onkeydown=e=>{if(e.target?.id==='linked-topic-search'){if(e.key==='Enter'){e.preventDefault();return;}if(e.key==='Escape'){e.preventDefault();e.target.value='';updateLinkedTopicSearch('');return;}}if(ui.edit?.kind==='details'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();try{saveInlineDetails();}catch(err){toast(err.message);}}else if(e.key==='Escape'&&hasDraft()){e.preventDefault();ui.edit=null;ui.noteDirty=false;ui.noteDraft=null;ui.noteRichDraft=null;render();}};
main.onchange=e=>{try{if(e.target.id==='f-nodeId'&&ui.edit?.kind==='plan'){ui.edit.draft.nodeId=e.target.value||null;return;}if(e.target.dataset.check||e.target.dataset.planCheck){if(guardDraft()){render();return;}}if(e.target.dataset.check){const id=e.target.dataset.check;commit(s=>setCompletion(s.nodes,id,e.target.checked));}if(e.target.dataset.planCheck){const id=e.target.dataset.planCheck;commit(s=>s.plans.find(x=>x.id===id).done=e.target.checked);}}catch(err){toast(err.message);render();}};
main.onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){
 case 'choose-syllabus':await chooseSyllabus(b.dataset.syllabus);break;
 case 'format-note':{const editor=$('#inline-notes');if(!editor||!applyRichFormat(editor,b.dataset.format,b.dataset.color)){toast('Select some note text first.');break;}ui.noteRichDraft=readRichEditor(editor);ui.noteDraft=richText(ui.noteRichDraft);ui.noteDirty=true;break;}
 case 'export-note-pdf':{const n=state.nodes.find(n=>n.id===id),runs=readRichEditor($('#inline-notes'));exportNotePDF(n.title,syllabusName(),runs);toast('Choose Save as PDF in the print dialog.');break;}
 case 'toggle-topic-picker':if(ui.edit?.kind!=='plan')break;capturePlanFields();ui.edit.pickerOpen=!ui.edit.pickerOpen;render();if(ui.edit.pickerOpen)setTimeout(()=>$('#linked-topic-search')?.focus(),20);break;
 case 'pick-linked-topic':if(ui.edit?.kind!=='plan')break;capturePlanFields();ui.edit.draft.nodeId=b.dataset.nodeId||null;ui.edit.pickerOpen=false;ui.edit.topicQuery='';render();break;
 case 'edit-goals':if(guardDraft())break;ui.edit={kind:'goals',draft:{goalMain:typeof state.settings.goalMain==='string'?state.settings.goalMain:'NIT Jamshedpur',goalBackup:typeof state.settings.goalBackup==='string'?state.settings.goalBackup:'BIT Mesra'}};render();focusInline('#inline-form');break;
 case 'more':if(guardDraft())break;ui.more=ui.more===id?null:id;ui.tab='description';ui.copyId=null;ui.noteDraft=null;ui.noteRichDraft=null;render();if(ui.more)focusInline('#panel-'+id);break;
 case 'topic-tab':if(guardDraft())break;ui.tab=b.dataset.tab;ui.noteDraft=null;ui.noteRichDraft=null;ui.copyId=null;render();break;
 case 'save-details':saveInlineDetails();break;
 case 'cancel-inline':ui.edit=null;render();break;
 case 'save-notes':{const runs=readRichEditor($('#inline-notes')),text=richText(runs);ui.noteDirty=false;ui.noteDraft=null;ui.noteRichDraft=null;commit(s=>Object.assign(s.nodes.find(n=>n.id===id),{notes:text,notesRich:runs}));toast('Notes saved');break;}
 case 'cancel-notes':ui.noteDirty=false;ui.noteDraft=null;ui.noteRichDraft=null;render();break;
 case 'week':if(guardDraft())break;plannerWeek=b.dataset.date;plannerDate=plannerWeek;render();break;
 case 'add-root':editNode(null);break;case 'add-node':editNode(null,id);break;case 'edit-node':editNode(id);break;
 case 'delete-node':{if(guardDraft())break;const n=state.nodes.find(x=>x.id===id),count=descendants(state.nodes,id).length;if(confirm(`Delete “${n.title}” and its ${count-1} descendants? Related planner tasks will stay, with their topic links removed. Export a backup first.`)){const parent=n.parentId;commit(s=>removeNode(s,id));location.hash=parent?'node/'+parent:'subjects';}break;}
 case 'notes':if(guardDraft())break;ui.more=id;ui.tab='notes';render();break;
 case 'add-link':if(guardDraft())break;ui.edit={kind:'link',id,type:b.dataset.type,draft:{label:'',url:''}};render();focusInline('#inline-form');break;
 case 'delete-link':if(guardDraft())break;commit(s=>s.nodes.find(x=>x.id===id).links.splice(Number(b.dataset.index),1));break;
 case 'copy-link':{const url=topicLink(id);try{await navigator.clipboard.writeText(url.href);toast('Direct link copied');}catch{ui.copyId=id;render();$('#copy-topic-link')?.select?.();}break;}
 case 'add-plan':editPlan(null,b.dataset.date||plannerDate);break;case 'edit-plan':editPlan(id);break;case 'delete-plan':if(guardDraft())break;if(confirm('Delete this task?'))commit(s=>s.plans=s.plans.filter(p=>p.id!==id));break;
 case 'suggest-plan':if(guardDraft())break;if(state.plans.some(x=>x.date===plannerDate)){if(!confirm('This day already has tasks. Add four more suggested tasks totaling 150 minutes?'))break;}commit(s=>{for(const [title,minutes] of [['Maths: one concept + examples',75],['Reasoning / Quant: timed practice',35],['Computer / English: alternate day',20],['Review mistakes',20]])s.plans.push({id:uid(),title,date:plannerDate,minutes,nodeId:null,done:false});});break;
 case 'log-session':if(guardDraft())break;edit('Study minutes log',field('title','What did you study?','','text','required maxlength="1000"')+field('date','Study date',today(),'date','required')+field('minutes','Actual study minutes',30,'number','min="1" max="1440" required'),v=>commit(s=>s.sessions.push({...v,id:uid(),minutes:Number(v.minutes)})));break;
 case 'delete-session':if(confirm('Delete this study log?'))commit(s=>s.sessions=s.sessions.filter(x=>x.id!==id));break;
 case 'add-test':editTest();break;case 'edit-test':editTest(id);break;case 'delete-test':if(confirm('Delete this test result?'))commit(s=>s.tests=s.tests.filter(x=>x.id!==id));break;
 case 'preferences':if(guardDraft())break;edit('Study preferences',field('milestone','Provisional milestone (not an official exam date)',state.settings.milestone,'date','required')+field('dailyMinutes','Daily study target in minutes',state.settings.dailyMinutes,'number','min="30" max="1440" required')+field('weekAnchor','Week 1 starts (Monday)',state.settings.weekAnchor,'date','required'),v=>commit(s=>Object.assign(s.settings,{milestone:v.milestone,dailyMinutes:Number(v.dailyMinutes),weekAnchor:weekStart(v.weekAnchor)})));break;
 case 'export':exportBackup();break;case 'recover':download('abhyas-local-recovery.json',localStorage.getItem(key)||'null');break;
 case 'import':$('#import-file').click();$('#import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>800000)throw new Error('The backup exceeds 800 KB.');const next=profileBackup(JSON.parse(await f.text()),activeSyllabus);if(confirm('Replace the entire current tracker with this backup? Export your current data first.')){commit(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,next);if(!s.settings.weekAnchor)s.settings.weekAnchor=weekStart([today(),...s.plans.map(p=>p.date)].sort()[0]);});toast('Backup imported · cloud changes pending if signed in');}}catch(err){toast('Import rejected: '+err.message);}};break;
 case 'login':if(!firebaseConfig||!cloud?.auth){toast('Fill in the configuration using the Firebase setup guide first.');break;}b.disabled=true;await cloud.login();break;
 case 'logout':if(dirty&&!confirm('This account has changes pending cloud sync. Its local copy will remain available for this account. Sign out?'))break;await cloud.logout();break;
 case 'sync-now':if(cloud?.user){await cloud.retry();toast('Sync retry requested. Check the status above.');}else toast('Configure Firebase and sign in with Google to use cloud sync.');break;
 case 'resolve-cloud':if(confirm('Export a local backup first. Replace the current tracker with the cloud version?'))await cloud.resolve(false);render();break;
 case 'resolve-local':if(confirm('Replace the cloud tracker with this local version? Changes from another device may be lost.'))await cloud.resolve(true);render();break;
 }}catch(err){toast(err.code||err.message);}finally{b.disabled=false;}};
$('#theme').onclick=()=>{if(guardDraft())return;try{commit(s=>s.settings.theme=s.settings.theme==='dark'?'light':'dark');}catch(e){toast(e.message);}};
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){history.replaceState(null,'',lastHash);main.focus();return;}if(hasDraft()){history.replaceState(null,'',lastHash);toast('Save or cancel your current changes first.');return;}lastHash=location.hash||'#home';resetUI();runSearch('');$('#global-search').value='';render();window.scrollTo(0,0);main.focus();});
window.addEventListener('online',()=>{schedule(0);if(!cloud?.user)$('#sync').textContent='Sign-in required';});window.addEventListener('offline',()=>$('#sync').textContent='Offline · saved locally, cloud pending');
window.addEventListener('storage',e=>{if(e.key===key){tabConflict=true;toast('Another tab changed this tracker. Use one tab to avoid conflicts; export JSON and reload.');if(cloud){cloud.blocked=true;$('#sync').textContent='Another tab changed data · export and reload';}}});
load();render();$('#sync').textContent=firebaseConfig?'Checking sign-in…':'Firebase setup required · sign-in unavailable';
$('#switch-syllabus').onclick=()=>{try{openSyllabusChooser();}catch(e){toast(e.message);}};
if(firebaseConfig){cloud=new CloudSync({
 status:msg=>{$('#sync').textContent=msg;if($('#cloud-detail'))$('#cloud-detail').textContent=msg;if(cloud?.remote&&['#settings','#account'].includes(location.hash)&&!dlg.open&&!hasDraft())render();},
 account:user=>{authReady=true;const uid=user?.uid||null;if(uid!==currentUid){activeSyllabus=null;cloud.documentId=null;currentUid=uid;}if(activeSyllabus){key=profileKey(activeSyllabus,uid);load();}resetUI();epoch++;if(dlg.open)dlg.close();render();},
 emptyState:()=>profileSeed(activeSyllabus||'nimcet',records,jilcce),
 validateRemote:s=>profileBackup(s,activeSyllabus||'nimcet'),
 cachedRevision:()=>{try{return JSON.parse(localStorage.getItem(key))?.revision??0;}catch{return 0;}},
 isDirty:()=>dirty,isEditing:()=>dlg.open||hasDraft(),getState:()=>state,getEpoch:()=>epoch,
 apply:s=>{state=profileBackup(s,activeSyllabus||'nimcet');ensureWeekAnchor();dirty=false;resetUI();persist();render();},ack:at=>{if(epoch===at)dirty=false;persist();},forceDirty:()=>{dirty=true;epoch++;persist();},schedule
 });cloud.documentId=null;cloud.init(firebaseConfig).catch(e=>{authReady=true;render();$('#sync').textContent='Firebase unavailable · sign-in required';toast('Firebase: '+(e.code||e.message));});}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>toast('Offline installation unavailable; online tracker works.'));
setInterval(()=>{if(cloud?.user&&activeSyllabus&&(location.hash||'#home')==='#home'&&!dlg.open&&!hasDraft())render();},60000);
